		3'b101:begin Hexo<=Hexs[23:20];		AN<=4'b1101;p<=point[5];LE<=LES[5];end
		3'b110:begin Hexo<=Hexs[27:24];		AN<=4'b1011;p<=point[6];LE<=LES[6];end
		3'b111:begin Hexo<=Hexs[31:28];		AN<=4'b0111;p<=point[7];LE<=LES[7];end
	endcase
	end
