module up_down_counter (CLK, RST, UP_DOWN, Q);
input CLK, RST, UP_DOWN;
output reg [3:0] Q;

always @(posedge CLK) begin
    if (RST) begin
        Q <= 4'b0000;
    end else if (UP_DOWN) begin
        Q <= Q + 1;
    end else begin
        Q <= Q - 1;
    end
end

endmodule

