module top_module(
  input data_in,
  input clk_in,
  input clk_out,
  output reg data_out
);reg [1:0] sync_reg;
  reg pulse;

  always @(posedge clk_in) begin
    sync_reg <= {sync_reg[0], data_in};
    pulse <= 1'b1;
  end

  always @(posedge clk_out) begin
    if (pulse) begin
      data_out <= sync_reg[1];
      pulse <= 1'b0;
    end
  end

endmodule

