module fsm (
    input clk,
    input reset,
    input j,
    output reg m);

    parameter BEGIN=0, TRANSITION=1, VERIFY=2, FINAL=3;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= BEGIN;
        else state <= next;
    end

    always_comb begin
        case (state)
            BEGIN: next = j ? TRANSITION : BEGIN;
            TRANSITION: next = j ? TRANSITION : VERIFY;
            VERIFY: next = j ? TRANSITION : FINAL;
            FINAL: next = j ? TRANSITION : BEGIN;
            default: next = 'x;
        endcase
    end

    assign m = (state == FINAL);

endmodule

