module traffic_light (
	input clk,
	input resetn,
	output reg [1:0] light_ns,
	output reg [1:0] light_ew);

	parameter NS_GREEN=0, NS_YELLOW=1, EW_GREEN=2, EW_YELLOW=3;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= NS_GREEN;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			NS_GREEN: next_state = EW_YELLOW;
			NS_YELLOW: next_state = EW_GREEN;
			EW_GREEN: next_state = NS_YELLOW;
			EW_YELLOW: next_state = NS_GREEN;
			default: next_state = NS_GREEN;
		endcase
	end

	always @(state) begin
		case (state)
			NS_GREEN: begin
				light_ns = 2'b10;
				light_ew = 2'b00;
			end
			NS_YELLOW: begin
				light_ns = 2'b01;
				light_ew = 2'b00;
			end
			EW_GREEN: begin
				light_ns = 2'b00;
				light_ew = 2'b10;
			end
			EW_YELLOW: begin
				light_ns = 2'b00;
				light_ew = 2'b01;
			end
			default: begin
				light_ns = 2'b00;
				light_ew = 2'b00;
			end
		endcase
	end
endmodule

