module traffic_light (
    input clk,
    input reset,
    output reg red,
    output reg yellow,
    output reg green
);

    // Define state encoding
    typedef enum reg [1:0] {
        RED = 2'b00,
        GREEN = 2'b01,
        YELLOW = 2'b10
    } state_t;

    state_t state, next_state;
    reg [3:0] counter;

    // State transition logic
    always @(*) begin
        case (state)
            RED: begin
                if (counter == 7)
                    next_state = GREEN;
                else
                    next_state = RED;
            end
            GREEN: begin
                if (counter == 10)
                    next_state = YELLOW;
                else
                    next_state = GREEN;
            end
            YELLOW: begin
                if (counter == 3)
                    next_state = RED;
                else
                    next_state = YELLOW;
            end
            default: next_state = RED; // Default state
        endcase
    end

    // State register and counter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RED;
            counter <= 0;
        end else begin
            if (counter == ((state == RED) ? 7 : (state == GREEN) ? 10 : 3))
                counter <= 0;
            else
                counter <= counter + 1;

            state <= next_state;
        end
    end

    // Output logic
    always @(*) begin
        // Default values
        red = 0;
        yellow = 0;
        green = 0;

        case (state)
            RED: red = 1;
            GREEN: green = 1;
            YELLOW: yellow = 1;
        endcase
    end

endmodule

