description:
Design a digital circuit that serves as a dual-phase sample-and-hold mechanism for an 8-bit input. On the rising edge of the `pla_ph1` signal, upon reset conditions, the circuit captures the 8-bit input `padd` and latches it into a temporary register. On the rising edge of the `pla_ph2` signal, it outputs the latched value to `out2_r`, unless the `dsp_reset` signal is active, in which case both output and latch are cleared to zero. This module effectively syncs the input data with two distinct clock phases, enabling controlled data flow and reset capability.
module top_module(
   // Outputs
   out2_r,
   // Inputs
   pla_ph1, pla_ph2, dsp_reset, padd
   );

code:
module top_module(
   // Outputs
   out2_r,
   // Inputs
   pla_ph1, pla_ph2, dsp_reset, padd
   );input pla_ph1, pla_ph2, dsp_reset;
   input [7:0] padd;
   output [7:0] out2_r;

   wire 	pla_ph1, pla_ph2, dsp_reset;
   wire [7:0] 	padd;
   reg [7:0] 	out2_r;

   reg [7:0] 	latched_r;

   always @(posedge pla_ph1 or posedge dsp_reset) begin
      if (dsp_reset)
         latched_r <= 8'h00;
      else
         latched_r <= padd;
   end

   always @(posedge pla_ph2 or posedge dsp_reset) begin
      if (dsp_reset)
         out2_r <= 8'h00;
      else
         out2_r <= latched_r;
   end

endmodule

