description:
Develop a reset synchronizer circuit that integrates a specified number of stages to ensure a clean synchronization of an active-low reset signal, `reset_n`, with a clock signal, `clk`. This module generates a synchronized output, `reset_n_sync`, which effectively filters glitches that may occur on the reset signal, ensuring that the receiving logic sees a stable reset state during power-up or external resets. The design employs a series of flip-flops in a pipeline manner, where the number of stages is configurable via the parameter `RESET_SYNC_STAGES`, allowing for improved reliability in systems where timing uncertainty might otherwise lead to erroneous operation.
module top_module(
    input reset_n,
    input clk,
    output [NUM_RESET_OUTPUT-1:0] reset_n_sync
);

code:
module top_module(
    input reset_n,
    input clk,
    output [NUM_RESET_OUTPUT-1:0] reset_n_sync
);parameter RESET_SYNC_STAGES = 4;
parameter NUM_RESET_OUTPUT = 1;

reg [RESET_SYNC_STAGES+NUM_RESET_OUTPUT-2:0] reset_reg /*synthesis dont_merge */;

generate
genvar i;
    for (i=0; i<RESET_SYNC_STAGES+NUM_RESET_OUTPUT-1; i=i+1) begin: reset_stage
        always @(posedge clk or negedge reset_n) begin
            if (~reset_n) begin
                reset_reg[i] <= 1'b0;
            end else begin
                if (i==0) begin
                    reset_reg[i] <= 1'b1;
                end else if (i < RESET_SYNC_STAGES) begin
                    reset_reg[i] <= reset_reg[i-1];
                end else begin
                    reset_reg[i] <= reset_reg[RESET_SYNC_STAGES-2];
                end
            end
        end
    end
endgenerate

assign reset_n_sync = reset_reg[RESET_SYNC_STAGES+NUM_RESET_OUTPUT-2:RESET_SYNC_STAGES-1];

endmodule

