module counter#(
    parameter WIDTH = 8
)(
    input wire clk,
    input wire rst,
    input wire en,
    output reg [WIDTH-1:0] count,
    output wire carry_out
);

always @(posedge clk or negedge rst) begin
    if (~rst) begin
        count <= 0;
    end else if (en) begin
        if (count == {WIDTH{1'b1}}) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end
end

assign carry_out = (count == {WIDTH{1'b1}}) && en;

endmodule

