module top_module(
	input clk,
	input reset,
	input [63:0] in,
	output reg [63:0] out);reg [63:0] d_last;

	always @(posedge clk) begin
		d_last <= in;
		if (reset)
			out <= '1;
		else
			out <= out & ~(in & ~d_last);
	end

endmodule

